// YEAR-SIM-1 and SAY-DO-1: /year shows the measured unattended horizon (a year of faults injected into the real recovery code) and every place
// where what the system says differs from what its code does. Both modules are generated by the watchdog run (foundation/yearsim.py,
// foundation/saydo.py); nothing on the page is typed by hand. JSON at /year.json.
import YEAR from "./yearsim-data.js";
import SAYDO from "./saydo-data.js";

const esc = s => String(s === null || s === undefined ? "" : s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const days = d => (d === null || d === undefined ? "unmeasured" : d + " days");
const MODE = { recovers: "Recovers by itself", degrades: "Keeps running, slower", fatal: "Stops until a person acts" };

export function yearBody(y = YEAR, s = SAYDO) {
  let h = "<div class=\"head\"><h1>A year unattended, measured</h1>";
  if (!y.measured) return h + "<p>The year simulation has not run yet. It runs on every watchdog pass.</p></div>";
  h += "<p id=\"st\" role=\"status\">" + (y.meets_target ? "Meets" : "Below") + " the target of " + esc(y.target_days) + " days. In 1 of 10 simulated years the system stops shipping by day "
    + esc(y.horizon.p10) + "; half reach day " + esc(y.horizon.p50) + ". Measured " + esc(y.at) + " from " + esc(y.runs) + " simulated years.</p></div>";
  h += "<div class=\"us-grid c2\">"
    + "<div class=\"card\"><h3 class=\"card-title\">Unattended horizon</h3><p class=\"meta\">10th percentile " + esc(days(y.horizon.p10)) + ", median " + esc(days(y.horizon.p50))
    + ". Share of years that reach the target: " + esc(Math.round((y.horizon.survive_year || 0) * 100)) + "%.</p></div>"
    + "<div class=\"card\"><h3 class=\"card-title\">If every sign-in and card fails</h3><p class=\"meta\">10th percentile " + esc(days(y.strict.p10)) + ". These are the acts only the owner's identity can do.</p></div>"
    + "<div class=\"card\"><h3 class=\"card-title\">Ships on its own</h3><p class=\"meta\">" + esc(y.self_rate_per_day === null ? "unmeasured" : y.self_rate_per_day + " substantive changes a day")
    + " originated by the server itself (target 1). Release horizon " + esc(days(y.release_horizon_p10)) + ".</p></div>"
    + (s.measured ? "<div class=\"card\"><h3 class=\"card-title\">Says what it does</h3><p class=\"meta\">" + esc(s.total - s.gaps) + " of " + esc(s.total) + " statements match the code (" + esc(Math.round((s.match_share || 0) * 1000) / 10) + "%). Gaps are listed below.</p></div>" : "")
    + "</div>";
  h += "<h2>What a year throws at it</h2><p>Each fault is injected into the code that should recover from it. A drill marked declared did not exercise code and is listed as a gap.</p>"
    + "<div class=\"us-wrap\"><table class=\"us-table\"><thead><tr><th>Fault</th><th>A year</th><th>What the system does</th><th>Evidence</th></tr></thead><tbody>"
    + y.classes.map(c => "<tr><td>" + esc(c.what) + "</td><td>" + esc(c.rate === null || c.rate === undefined ? "dated" : c.rate + "x") + "<br><small>" + esc(c.basis) + "</small></td><td class=\""
      + (c.recover && c.exercised ? "us-pass" : "us-fail") + "\">" + esc(MODE[c.mode] || c.mode) + " (" + esc(Math.round(c.capacity * 100)) + "% capacity)" + (c.exercised ? "" : ", declared") + "</td><td><small>" + esc(c.evidence) + "</small></td></tr>").join("")
    + "</tbody></table></div>";
  if (y.findings && y.findings.length) h += "<h2>What it is fixing</h2><ul>" + y.findings.map(f => "<li>" + esc(f.id) + ": " + esc(f.why) + "</li>").join("") + "</ul>";
  if (s.measured) {
    h += "<h2 id=\"say-do\">Says and does</h2><p>Every rule in the agent instructions, every claim on this site, every change the server made itself, the second loop and the year target are checked against the code on every watchdog pass.</p>"
      + "<ul>" + Object.entries(s.summary).map(([k, v]) => "<li>" + esc(k) + ": " + esc(v.total - v.gaps) + " of " + esc(v.total) + " match</li>").join("") + "</ul>";
    if (s.gap_list.length) h += "<div class=\"us-wrap\"><table class=\"us-table\"><thead><tr><th>Source</th><th>Statement</th><th>What differs</th></tr></thead><tbody>"
      + s.gap_list.map(g => "<tr><td>" + esc(g.source) + "</td><td>" + esc(g.id) + "</td><td><small>" + esc(g.detail) + "</small></td></tr>").join("") + "</tbody></table></div>"
      + (s.omitted ? "<p class=\"meta\">" + esc(s.omitted) + " more in /year.json.</p>" : "");
  }
  return h + "<p class=\"meta\">After W. Ross Ashby's ultrastable system: the essential variables, their bounds and the second loop that changes the system when one stays out are on <a href=\"/how#why-ultrastable\">How it works</a>.</p>";
}

export function yearRoutes(u, shell, HTML) {
  const p = u.pathname.replace(/\/$/, "");
  if (p === "/year.json") return new Response(JSON.stringify({ year: YEAR, saydo: SAYDO }), { headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*", "Cache-Control": "public, max-age=300" } });
  if (p === "/year") return new Response(shell({ path: "/year", title: "A year unattended, measured - Ultrastable", description: "The measured unattended horizon: a year of faults injected into the system's own recovery code, and every place its words differ from its code." }, yearBody()), { headers: { ...HTML, "Cache-Control": "public, max-age=300" } });
  return null;
}
